{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_2af92e5cfac0fcb9a7288c7e", "claim_ids": ["claim_6edeba07cb0873e118bb5b78", "claim_d1fd8b73c4da9a6e55cf051d"], "query_ids": ["q_192"], "claims": [{"claim_id": "claim_6edeba07cb0873e118bb5b78", "quote": "the subject LCD display module is classified in heading 8528, specifically subheading 8528.59.25, HTSUS", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Gregory Connor, Chief Electronics, Machinery, Automotive, and International Nomenclature Branch", "tariff_program": "HTSUS", "affected_product": "LCD display module", "hts_code": "8528.59.25", "duty_rate": "free"}}, {"claim_id": "claim_d1fd8b73c4da9a6e55cf051d", "quote": "CBP classified in heading 8531, HTSUS, a “Heads Up” automotive LCD display designed to provide limited, easily understood information ( i.e., speed, safety warnings, turn-by-turn directions, and audio settings) to the driver", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "CBP", "tariff_program": "HTSUS", "duty_rate": "free"}}]}, {"pair_id": "conflict_64e19311d182b544dd4d67bc", "claim_ids": ["claim_6edeba07cb0873e118bb5b78", "claim_ea27829fd6af40788cd129b9"], "query_ids": ["q_192"], "claims": [{"claim_id": "claim_6edeba07cb0873e118bb5b78", "quote": "the subject LCD display module is classified in heading 8528, specifically subheading 8528.59.25, HTSUS", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Gregory Connor, Chief Electronics, Machinery, Automotive, and International Nomenclature Branch", "tariff_program": "HTSUS", "affected_product": "LCD display module", "hts_code": "8528.59.25", "duty_rate": "free"}}, {"claim_id": "claim_ea27829fd6af40788cd129b9", "quote": "In NY N306705, dated October 31, 2019, CBP classified LCD indicator panels for automobiles in heading 8531, HTSUS.", "url": "https://www.customsmobile.com/rulings/docview?doc_id=HQ+H325872&highlight=category%3AClassification", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "CBP", "tariff_program": "HTSUS", "affected_product": "LCD indicator panels for automobiles"}}]}, {"pair_id": "conflict_5f7cd22dc07be6a4955bfea5", "claim_ids": ["claim_72f11023dc47220745f6b32e", "claim_93b77e471e6e89244a0b1a88"], "query_ids": ["q_193"], "claims": [{"claim_id": "claim_72f11023dc47220745f6b32e", "quote": "For an automobile that is the product of South Korea with a Column 1 duty rate less than 15 percent ad valorem, the combined Column 1 and additional Section 232 duty rate is 15 percent ad valorem. Use heading 9903.94.61.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/3fe2566", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "affected_product": "automobile", "country_of_origin": "South Korea", "duty_rate": "15 percent ad valorem"}}, {"claim_id": "claim_93b77e471e6e89244a0b1a88", "quote": "South Korean automobiles exported to the United States will now be subject to a 15-percent tariff, down from the 25-percent tariff implemented", "url": "https://www.youtube.com/watch?v=0trOeEANSKs", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"exporting_country": "South Korea", "duty_rate": "15-percent", "effective_date": "now", "reported_policy_status": "implemented"}}]}, {"pair_id": "conflict_aed923bcd88e5aa964b90476", "claim_ids": ["claim_0d23f000b5d0be94c8b9c6f6", "claim_dc96049be2ad952982d40eaf"], "query_ids": ["q_194"], "claims": [{"claim_id": "claim_0d23f000b5d0be94c8b9c6f6", "quote": "special sectoral and national security tariffs on foreign automobiles, at 25%", "url": "https://www.newsfromthestates.com/article/us-japan-trade-deal-sets-15-tax-imported-vehicles-550b-investment-us", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "special sectoral and national security tariffs on foreign automobiles", "duty_rate": "25%"}}, {"claim_id": "claim_dc96049be2ad952982d40eaf", "quote": "Trump had threatened Japan in a letter earlier this month with a 25% \"reciprocal\" tariff on all Japanese goods set to begin Aug. 1, in addition to special sectoral and national security tariffs on foreign automobiles, at 25%", "url": "https://www.newsfromthestates.com/article/us-japan-trade-deal-sets-15-tax-imported-vehicles-550b-investment-us", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Trump", "tariff_program": "25% \"reciprocal\" tariff on all Japanese goods", "duty_rate": "25%", "effective_date": "Aug. 1"}}]}, {"pair_id": "conflict_8b41fd4263363f8d25f5d703", "claim_ids": ["claim_028d1c5d8c80d2d267d7387b", "claim_7bc5f8964422e027e5ca2221"], "query_ids": ["q_194"], "claims": [{"claim_id": "claim_028d1c5d8c80d2d267d7387b", "quote": "Chief Cabinet Secretary Yoshimasa Hayashi said the parties agreed to a 15% tariff on Japanese vehicles and auto parts imported into the U.S. without any volume restrictions", "url": "https://www.newsfromthestates.com/article/us-japan-trade-deal-sets-15-tax-imported-vehicles-550b-investment-us", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "15% tariff on Japanese vehicles and auto parts imported into the U.S.", "duty_rate": "15%"}}, {"claim_id": "claim_7bc5f8964422e027e5ca2221", "quote": "It was 27 and 1/2%. This is almost a a halving of the tariff rate.", "url": "https://www.youtube.com/watch?v=Z1tBMyx8rPU", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "27 and 1/2%"}}]}, {"pair_id": "conflict_2c1daada4cd132d968286b35", "claim_ids": ["claim_29f0d7830a4384a24d3a3633", "claim_cf2fe71d4a07f6b4d882184d"], "query_ids": ["q_198"], "claims": [{"claim_id": "claim_29f0d7830a4384a24d3a3633", "quote": "Tariffs on rigid and flex PCBs sourced from China typically range from 25% to 30%. This means higher costs for prototyping and production alike, complicating budgeting during early-stage design and putting pressure on already tight development cycles.", "url": "https://blog.matric.com/china-tariffs-on-electronics-manufacturers", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Tariffs on rigid and flex PCBs sourced from China", "duty_rate": "25% to 30%"}}, {"claim_id": "claim_cf2fe71d4a07f6b4d882184d", "quote": "| China | 30% DS/4Layer, 55% other | 14/05/25 | Until 12/11/25 | Interim deal; 90-day truce. |", "url": "https://www.icape-group.com/pcb-tariff-information", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "30% DS/4Layer, 55% other", "effective_date": "14/05/25", "expiration_date": "Until 12/11/25"}}]}, {"pair_id": "conflict_aa3de39ca6a3183390b7093b", "claim_ids": ["claim_6895fc2376c9a257563df81d", "claim_cf2fe71d4a07f6b4d882184d"], "query_ids": ["q_198"], "claims": [{"claim_id": "claim_6895fc2376c9a257563df81d", "quote": "In April 2025, the United States has implemented new tariffs on Chinese imports, including printed circuit boards (PCBs) and custom-made technical parts.", "url": "https://www.icape-group.com/pcb-tariff-information", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "ICAPE Group", "tariff_program": "new tariffs on Chinese imports", "affected_product": "printed circuit boards (PCBs) and custom-made technical parts", "effective_date": "April 2025"}}, {"claim_id": "claim_cf2fe71d4a07f6b4d882184d", "quote": "| China | 30% DS/4Layer, 55% other | 14/05/25 | Until 12/11/25 | Interim deal; 90-day truce. |", "url": "https://www.icape-group.com/pcb-tariff-information", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "30% DS/4Layer, 55% other", "effective_date": "14/05/25", "expiration_date": "Until 12/11/25"}}]}, {"pair_id": "conflict_90a92dbb0a225095cea71151", "claim_ids": ["claim_0728551e1ef3ac679ae0cf62", "claim_3191cfa240904643194c9262"], "query_ids": ["q_2"], "claims": [{"claim_id": "claim_0728551e1ef3ac679ae0cf62", "quote": "On March 26, President Trump signed a proclamation to impose a 25% tariff on all imported automobiles and certain automobile parts to address “a critical threat to U.S. national security,” according to a White House Fact Sheet.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "President Trump", "tariff_program": "25% tariff on all imported automobiles and certain automobile parts", "legal_authority": "International Emergency Economic Powers Act (IEEPA)", "effective_date": "April 3 at 12:01 am EDT"}}, {"claim_id": "claim_3191cfa240904643194c9262", "quote": "A new 25% tariff on imported auto parts officially took effect at 12:01 a.m. EDT on May 3.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariff on imported auto parts", "duty_rate": "25%", "effective_date": "May 3"}}]}, {"pair_id": "conflict_41dd0d9a2b68f2c6cf20b53c", "claim_ids": ["claim_1fcaebabb2dc8dab408c64a5", "claim_3bcbfa5acd6572abcda72a7b"], "query_ids": ["q_2"], "claims": [{"claim_id": "claim_1fcaebabb2dc8dab408c64a5", "quote": "Canada and Mexico-origin goods that do not meet USMCA standards will face 25% tariffs.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs", "country_of_origin": "Canada and Mexico-origin goods that do not meet USMCA standards"}}, {"claim_id": "claim_3bcbfa5acd6572abcda72a7b", "quote": "Trump has imposed new 20% duties on Chinese imports, reinstated 25% tariffs on global steel and aluminum, and applied 25% tariffs on certain imports from Canada and Mexico that do not comply with a North American trade agreement over the U.S. fentanyl overdose crisis.", "url": "https://www.automotive-fleet.com/news/tariff-update-may-30-tariff-shifts-shake-up-auto-industry-as-legal-trade-battles-evolve", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Trump", "tariff_program": "new 20% duties on Chinese imports, reinstated 25% tariffs on global steel and aluminum, and applied 25% tariffs on certain imports from Canada and Mexico", "duty_rate": "20%"}}]}, {"pair_id": "conflict_b3cea13a34206119f94eb413", "claim_ids": ["claim_004b9b23667a1f7edf15dc4e", "claim_8f6500b9c31e85c37795c67e"], "query_ids": ["q_202"], "claims": [{"claim_id": "claim_004b9b23667a1f7edf15dc4e", "quote": "In response, the administration invoked Section 122 of the Trade Act of 1974 to impose a 10 percent across-the-board import surcharge on goods from nearly all countries for 150 days. On May 7, 2026, the Court of International Trade ruled against the Section 122 tariffs, though the decision is under appeal and tariffs continue to be collected.", "url": "https://www.atlanticcouncil.org/programs/geoeconomics-center/trump-tariff-tracker", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 122", "legal_authority": "Trade Act of 1974", "duty_rate": "10 percent", "reported_policy_status": "under appeal and tariffs continue to be collected"}}, {"claim_id": "claim_8f6500b9c31e85c37795c67e", "quote": "Section 122, which provides a temporary authority to impose tariffs without an investigation, but is limited to a 15 percent rate for only 150 days.", "url": "https://budgetlab.yale.edu/research/state-us-tariffs-scotus-ruling-update", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 122", "duty_rate": "15 percent"}}]}]}

